(async () => {
    const viewport = visibleList().querySelector(".virtual-list-viewport");
    const list = visibleList();
    const frame = () => new Promise(requestAnimationFrame);
    const dimensions = () => ({
        top: viewport.scrollTop,
        height: viewport.scrollHeight,
        clientHeight: viewport.clientHeight,
        width: viewport.scrollWidth,
        visibility: document.visibilityState,
    });
    const phases = {};
    let direction = 1;
    let appliedPan;
    const bounce = () => {
        const max = viewport.scrollHeight - viewport.clientHeight;
        if (viewport.scrollTop >= max - 1) direction = -1;
        if (viewport.scrollTop <= 0) direction = 1;
    };
    async function phase(name, duration, step) {
        const before = dimensions();
        const start = performance.now();
        const times = [];
        const top = [];
        let index = 0;
        while (performance.now() - start < duration) {
            const timestamp = await frame();
            times.push({timestamp, at: performance.now()});
            step?.(index++);
            top.push(viewport.scrollTop);
        }
        phases[name] = {before, after: dimensions(), start, times, top};
    }

    viewport.scrollTop = 0;
    await frame();
    await frame();
    await phase("idle", 3000);
    await phase("vscroll-drift", 4000, () => {
        bounce();
        const p = point(list, "message");
        wheel(p.x, p.y, 2 * direction, 14 * direction);
        viewport.scrollTop += 14 * direction;
    });
    await phase("pan-message", 4000, (index) => {
        const p = point(list, "message");
        wheel(p.x, p.y, Math.floor(index / 45) % 2 === 0 ? 8 : -8, 0);
    });
    for (let i = 0; i < 20; i++) {
        const p = point(list, "message");
        wheel(p.x, p.y, 8, 0);
        await frame();
    }
    appliedPan = list.querySelector("[data-message-summary] > span")?.style.marginLeft ?? null;
    await phase("vscroll-panned", 4000, () => {
        bounce();
        viewport.scrollTop += 14 * direction;
    });
    return {tab: document.querySelector("[data-tab-id].active")?.dataset.tabId,
            mountedGraphs: document.querySelectorAll("[role=listbox] .virtual-list-viewport").length,
            appliedPan, phases};
})()

