// Drives the real app through the same gestures in each arm and marks each phase in
// the perf samples, so frame gaps can be sliced per phase. Injected by serve.ts.
const invoke = (cmd, args) => window.__TAURI_INTERNALS__.invoke(cmd, args);
const mark = (name) =>
	invoke("perf_append", { lines: [JSON.stringify({ name: `probe:${name}`, ms: 0, kind: "span", at: Date.now(), attrs: { visibility: document.visibilityState } })] });
const frame = () => new Promise((r) => requestAnimationFrame(r));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const TABS = { sink: "4c632eee-0e08-43ab-8f7f-ec63b66b2162", trunk: "22400000-0000-4000-8000-000000000001" };
// Tabs activate on mousedown, not click.
const activate = (id) => document.querySelector(`[data-tab-id="${id}"]`)?.dispatchEvent(new MouseEvent("mousedown", { bubbles: true, button: 0 }));

function visibleList() {
	// Hidden tabs stay laid out under visibility: hidden, so a size says nothing.
	return [...document.querySelectorAll("[role=listbox]")].find((l) => getComputedStyle(l).visibility === "visible" && l.querySelector("[data-testid=commit-row]"));
}

function point(list, column) {
	const rows = [...list.querySelectorAll("[data-testid=commit-row]")].filter((r) => r.getBoundingClientRect().height > 0);
	const vp = list.querySelector(".virtual-list-viewport").getBoundingClientRect();
	const row = rows.find((r) => r.getBoundingClientRect().top > vp.top + 60) ?? rows[0];
	const cell = row.querySelector(`[data-column=${column}]`).getBoundingClientRect();
	return { x: cell.left + Math.min(40, cell.width / 2), y: cell.top + cell.height / 2 };
}

function wheel(x, y, deltaX, deltaY) {
	const target = document.elementFromPoint(x, y);
	target?.dispatchEvent(new WheelEvent("wheel", { bubbles: true, cancelable: true, clientX: x, clientY: y, deltaX, deltaY, deltaMode: 0 }));
}

async function phase(name, ms, step) {
	await mark(`${name}:start`);
	const end = performance.now() + ms;
	let i = 0;
	while (performance.now() < end) {
		step?.(i++);
		await frame();
	}
	await mark(`${name}:end`);
}

async function scenarios(tab) {
	const list = visibleList();
	const viewport = list.querySelector(".virtual-list-viewport");
	await mark(`${tab}:list:${viewport.scrollHeight}x${viewport.scrollWidth}/${viewport.clientWidth}`);
	await phase(`${tab}:idle`, 3000);
	let dir = 1;
	const bounce = () => {
		const max = viewport.scrollHeight - viewport.clientHeight;
		if (viewport.scrollTop >= max - 1) dir = -1;
		if (viewport.scrollTop <= 0) dir = 1;
	};
	await phase(`${tab}:vscroll-drift`, 4000, () => {
		bounce();
		const p = point(list, "message");
		wheel(p.x, p.y, 2 * dir, 14 * dir);
		viewport.scrollTop += 14 * dir;
	});
	await phase(`${tab}:pan-message`, 4000, (i) => {
		const p = point(list, "message");
		wheel(p.x, p.y, Math.floor(i / 45) % 2 === 0 ? 8 : -8, 0);
	});
	// Leave the Message pan off its start, so the scroll below runs the clamp that
	// every scroll event pays while the summaries are panned.
	for (let i = 0; i < 20; i++) {
		const p = point(list, "message");
		wheel(p.x, p.y, 8, 0);
		await frame();
	}
	await mark(`${tab}:panned:${[...list.querySelectorAll("[data-message-summary] > span")].map((s) => s.style.marginLeft)[0] ?? "none"}`);
	await phase(`${tab}:vscroll-panned`, 4000, () => {
		bounce();
		viewport.scrollTop += 14 * dir;
	});
	await phase(`${tab}:pan-graph`, 4000, (i) => {
		const p = point(list, "graph");
		wheel(p.x, p.y, Math.floor(i / 45) % 2 === 0 ? 8 : -8, 0);
	});
}

async function run() {
	while (!visibleList()) await sleep(200);
	await mark("ready");
	await sleep(6000);
	await scenarios("sink");
	activate(TABS.trunk);
	await sleep(4000);
	await scenarios("trunk");
	activate(TABS.sink);
	await sleep(1500);
	await mark("done");
}

run().catch((e) => mark(`error:${e}`));

