import json
from pathlib import Path
from summarize import consecutive_over

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / '.boris/probe-scroll/perf-2026-09-24/app'
PHASES = ('trunk:vscroll-drift', 'trunk:vscroll-panned', 'sink:vscroll-drift', 'sink:vscroll-panned')

results = {}
for path in sorted(SOURCE.glob('*-[123].jsonl')):
    rows = [json.loads(line) for line in path.read_text().splitlines()]
    results[path.name] = {}
    for phase in PHASES:
        start = next(row['at'] for row in rows if row['name'] == f'probe:{phase}:start')
        end = next(row['at'] for row in rows if row['name'] == f'probe:{phase}:end')
        samples = [row for row in rows if row['kind'] == 'frame-gap' and start < row['at'] <= end]
        over = [{'ordinal': index, 'elapsed_ms': row['at'] - start, 'gap_ms': row['ms']}
                for index, row in enumerate(samples) if row['ms'] > 25]
        results[path.name][phase] = {
            'max_ms': max(row['ms'] for row in samples),
            'longest_run_over_25ms': consecutive_over([row['ms'] for row in samples], 25),
            'gaps_over_25ms': over,
            'first_to_last_over_25ms_ms': over[-1]['elapsed_ms'] - over[0]['elapsed_ms'] if over else None,
        }

print(json.dumps(results, indent=2))

