import argparse
import json
import math
from pathlib import Path
from statistics import median

PHASE_MS = 4000
BURST_INTERVAL_MS = 25
BURST_WINDOW_MS = 400
BURST_COUNT = 10
CADENCE_MS = {60: (14, 20), 120: (6, 11)}
PHASES = ('long-scroll', 'long-idle', 'short-scroll')


def longest_consecutive(gaps):
    streak = best = 0
    for gap in gaps:
        streak = streak + 1 if gap > BURST_INTERVAL_MS else 0
        best = max(best, streak)
    return best


def phase_metrics(trace):
    stamps = trace['stamps']
    gaps = [end - start for start, end in zip(stamps, stamps[1:])]
    if not gaps or min(gaps) <= 0 or stamps[-1] - stamps[0] < PHASE_MS:
        raise ValueError('rAF timestamps are missing, unordered, or shorter than the phase')

    slow = [stamp - stamps[0] for stamp, gap in zip(stamps[1:], gaps) if gap > BURST_INTERVAL_MS]
    first = within = 0
    for last, stamp in enumerate(slow):
        while stamp - slow[first] > BURST_WINDOW_MS:
            first += 1
        within = max(within, last - first + 1)

    steps = trace['steps']
    return {'duration_ms': stamps[-1] - stamps[0], 'gaps': len(gaps), 'p50_ms': median(gaps),
            'max_ms': max(gaps), 'count_above_25ms': len(slow),
            'longest_consecutive_above_25ms': longest_consecutive(gaps),
            'max_count_in_400ms': within, 'burst': within >= BURST_COUNT,
            'step_count': len(steps),
            'travel_px': sum(abs(step['after'] - step['top']) for step in steps)}


def validate_trial(rate, traces):
    dimensions = {}
    metrics = {}
    for phase in PHASES:
        trace = traces[phase]
        measured = phase_metrics(trace)
        metrics[phase] = measured

        tab = phase.split('-')[0]
        before, after = trace['before'], trace['after']
        if before['visibility'] != 'visible' or after['visibility'] != 'visible' or trace['visibility']:
            raise ValueError(f'{phase}: page visibility changed')
        if before['tab'] != tab or after['tab'] != tab:
            raise ValueError(f'{phase}: wrong active repository')
        if before['top'] != 0 or any(before[key] != after[key]
                                     for key in ('height', 'clientHeight', 'clientWidth')):
            raise ValueError(f'{phase}: scroll origin or loaded height changed')
        position = (before['height'], before['clientHeight'], before['clientWidth'])
        if dimensions.get(tab, position) != position:
            raise ValueError('long phases used different viewport or history sizes')
        dimensions[tab] = position
        if phase == 'long-idle' and (after['top'] != 0 or measured['step_count']):
            raise ValueError('long idle moved')
        if phase.endswith('-scroll') and measured['travel_px'] <= 0:
            raise ValueError(f'{phase}: no motion')

    if dimensions['long'][0] < 10000 or dimensions['short'][0] >= 2500:
        raise ValueError(f'unexpected history depth: {dimensions}')

    low, high = CADENCE_MS[rate]
    observed = metrics['long-idle']['p50_ms']
    if not low <= observed <= high:
        raise ValueError(f'expected {low}..{high}ms idle cadence at {rate}Hz, observed {observed}ms')
    return metrics


def compare(pairs, control):
    long_only = sum(p['long-scroll']['burst'] and not p[control]['burst'] for p in pairs)
    control_only = sum(p[control]['burst'] and not p['long-scroll']['burst'] for p in pairs)
    discordant = long_only + control_only
    p_value = sum(math.comb(discordant, k) for k in range(long_only, discordant + 1)) / 2**discordant
    return {'long_only': long_only, 'control_only': control_only,
            'paired_exact_one_sided_p': p_value,
            'stronger_than_control_at_0.05': len(pairs) == 10 and p_value <= 0.05}


def summarize(path):
    results = {60: [], 120: []}
    receipts = []
    for attempt in sorted(path.glob('block-*/pair.json')):
        pair = json.loads(attempt.read_text())
        receipts.append(pair)
        if pair['status'] != 'admitted':
            continue
        for rate in results:
            results[rate].append(pair['rates'][str(rate)]['phase_metrics'])

    report = {}
    for rate, pairs in results.items():
        counts = {phase: sum(p[phase]['burst'] for p in pairs) for phase in PHASES}
        report[str(rate)] = {'admitted_pairs': len(pairs), 'bursts': counts,
                             'long_vs_idle': compare(pairs, 'long-idle'),
                             'long_vs_short': compare(pairs, 'short-scroll')}
        if pairs and counts['long-scroll'] == 0:
            report[str(rate)]['zero_bursts_one_sided_95_upper_bound'] = 1 - 0.05 ** (1 / len(pairs))
    return {'rate_summaries': report, 'pair_receipts': receipts}


if __name__ == '__main__':
    cli = argparse.ArgumentParser()
    cli.add_argument('cohort', type=Path)
    args = cli.parse_args()
    print(json.dumps(summarize(args.cohort), indent=2))

