async ({phase, duration}) => {
    const list = visibleList();
    const viewport = list.querySelector(".virtual-list-viewport");
    const moving = phase !== "long-idle";
    const frame = () => new Promise(requestAnimationFrame);
    const dimensions = () => ({
        tab: document.querySelector("[data-tab-id].active")?.dataset.tabId,
        visibility: document.visibilityState,
        top: viewport.scrollTop,
        height: viewport.scrollHeight,
        clientHeight: viewport.clientHeight,
        clientWidth: viewport.clientWidth,
    });

    viewport.scrollTop = 0;
    for (let settle = 0; settle < 4; settle++) await frame();

    const before = dimensions();
    const visibility = [];
    const visibilityChanged = () => visibility.push(document.visibilityState);
    document.addEventListener("visibilitychange", visibilityChanged);
    const start = await frame();
    const stamps = [start];
    const steps = [];
    let previousSlot = -1;
    let direction = 1;
    let stamp = start;
    while (stamp < start + duration) {
        const elapsed = stamp - start;
        const slot = Math.round(elapsed * 60 / 1000);
        if (moving && slot > previousSlot) {
            previousSlot = slot;
            const top = viewport.scrollTop;
            if (top >= viewport.scrollHeight - viewport.clientHeight - 1) direction = -1;
            if (top <= 0) direction = 1;

            const p = point(list, "message");
            wheel(p.x, p.y, 2 * direction, 14 * direction);
            viewport.scrollTop += 14 * direction;
            steps.push({stamp, slot, top, after: viewport.scrollTop});
        }

        stamp = await frame();
        stamps.push(stamp);
    }

    document.removeEventListener("visibilitychange", visibilityChanged);
    return {phase, before, after: dimensions(), stamps, steps, visibility};
}
